/**
 * Unified English UI chrome and runtime notice dictionary for ToolFlow.
 * Task options and stage details generated by the active LLM adapt to the user's prompt language.
 */
export const t = {
  analyzingTask: (task: string) => `Analyzing "${task}" and generating stage plan...`,
  cancelled: "Task execution cancelled.",
  noDecision: "No option selected. Exited.",
  resetSuccess: "[OK] Cleared active task state and caches.",
  exportNoBlueprint: "No active plan to export. Run `/toolflow <task>` first.",
  exportSuccess: (fileName: string) => `[OK] Exported blueprint to ${fileName}`,
  rollbackNothing: "No active blueprint or rollback point available.",
  rollbackSuccess: (stageNum: number, restoredCount: number, deletedCount: number) =>
    `[OK] Rolled back to Stage ${stageNum} (restored ${restoredCount}, removed ${deletedCount} file(s)).`,
  promptInserted: (cmd: string) => `Inserted prompt ${cmd} into editor.`,
  blueprintStart: (stageCount: number, title: string) =>
    `Plan ready (${stageCount} stages) -> Starting Stage 1: ${title}`,
  fastStart: (title: string) => `Fast track active -> ${title}`,
  allCompleted: (task: string) => `All stages completed for "${task}".`,
  stageVerified: (stageNum: number, artifact: string, shaPrefix: string) =>
    `Stage ${stageNum} verified: ${artifact} (${shaPrefix})`,
  circuitBroken: (stageNum: number, artifact: string) =>
    `Stage ${stageNum} paused after 3 remediation retries (${artifact}). Run \`/toolflow rollback\` or update manually.`,
  contextDehydrated: "Context compacted and stage logs archived.",
  noInteractiveUi: "Interactive UI unavailable. Use `/toolflow <task description>` directly.",
  helpBanner:
    "ToolFlow Commands:\n" +
    "  /toolflow                 - Open interactive Prompt Workbench & Blueprint Navigator\n" +
    "  /toolflow <task>          - Analyze task and run fast track or staged blueprint\n" +
    "  /toolflow fast <task>     - Force lightweight single-stage execution\n" +
    "  /toolflow status          - Show active blueprint stage and verification status\n" +
    "  /toolflow stats           - Show token savings ledger (dehydration, cache, guards)\n" +
    "  /toolflow rollback [n]    - Revert workspace changes to stage snapshot\n" +
    "  /toolflow export          - Export current blueprint to TOOLFLOW_BLUEPRINT.md\n" +
    "  /toolflow reset           - Clear active blueprint state and read caches",
  toolOutputDehydrated: (toolName: string, lines: number, savedTokens: number) =>
    `[Dehydrated] ${toolName} (${lines} lines -> ~${savedTokens} tokens saved)`,
  readCacheHitNotice: (file: string, tokens: number) =>
    `[Read Cache] ${file} unchanged, ~${tokens} tokens saved`,
  compactNotice: (tokensSaved?: number) =>
    tokensSaved
      ? `[ToolFlow] Stage history compacted (~${tokensSaved} tokens released)`
      : "[ToolFlow] Stage history compacted",
} as const;
